<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN','VERIFICADOR']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Asistencia — Hache Natación</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Arial,sans-serif;color:#172033}.wrap{max-width:920px;margin:auto;padding:72px 12px 32px}.head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}h1{font-size:27px;margin:0 0 4px}.sub{color:#64748b;font-size:13px}.fecha{width:100%;padding:12px;border:1px solid #cbd5e1;border-radius:12px;background:#fff;font-size:16px;margin:16px 0 8px}.resumen{font-size:12px;color:#64748b;margin:0 2px 16px}.jornada-actions{display:grid;grid-template-columns:1fr;gap:8px;margin-bottom:18px}.btn-danger{border:1px solid #fecaca;background:#fff;color:#991b1b;border-radius:10px;padding:10px 12px;font-weight:800;cursor:pointer}.bloque{margin:18px 0 24px}.bloque-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 2px 9px}.bloque-title{font-size:18px;font-weight:900}.bloque-sub{font-size:11px;color:#64748b;margin-top:2px}.bloque-cancel{border:0;background:#fff1f2;color:#9f1239;border-radius:9px;padding:8px 10px;font-weight:800;cursor:pointer}.clase{background:#fff;border-radius:16px;padding:14px;margin-bottom:10px;box-shadow:0 3px 12px #0000000d}.clase.cancelada{opacity:.72;background:#fff8f8}.clase-top{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:4px}.hora{font-size:20px;font-weight:900}.tipo{font-size:10px;color:#64748b;text-transform:uppercase;font-weight:800;letter-spacing:.05em}.estado{font-size:10px;font-weight:900;padding:5px 8px;border-radius:999px;background:#e2e8f0}.estado.cancel{background:#fee2e2;color:#991b1b}.alumno{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;border-top:1px solid #eef2f7;padding:11px 0}.nombre{font-weight:750}.info{font-size:11px;color:#64748b;margin-top:3px}.pase{display:flex;gap:5px}.pase button{border:0;border-radius:9px;padding:8px 10px;font-weight:900;cursor:pointer}.vino{background:#dcfce7;color:#166534}.no-vino{background:#fee2e2;color:#991b1b}.sel{outline:2px solid #172033}.justificada{display:inline-block;margin-left:5px;padding:2px 5px;border-radius:5px;background:#fef3c7;color:#92400e;font-weight:800}.bloqueado{font-size:10px;font-weight:900;color:#991b1b;background:#fee2e2;padding:6px 8px;border-radius:8px;white-space:nowrap}.clase-actions{display:flex;gap:7px;margin-top:9px}.clase-actions button{border:0;border-radius:9px;padding:9px 10px;font-weight:800;cursor:pointer;flex:1}.cerrar{background:#172033;color:#fff}.cancelar{background:#fff1f2;color:#9f1239}.vacio{text-align:center;color:#64748b;padding:30px 10px}.alerta{color:#991b1b;font-weight:700}.ok{color:#166534;font-weight:700}.motivo{font-size:11px;color:#991b1b;margin:8px 0 2px}.descanso{background:#fff;border-radius:16px;padding:28px 18px;text-align:center;box-shadow:0 3px 12px #0000000d}.descanso strong{display:block;font-size:18px;margin-bottom:6px}.descanso span{color:#64748b;font-size:13px}@media(min-width:700px){.wrap{padding-top:35px}.jornada-actions{display:flex;justify-content:flex-end}.jornada-actions button{width:auto}.alumno{grid-template-columns:1fr 210px}.pase button{padding:9px 16px}.clase{padding:16px 18px}}
</style></head><body><main class="wrap"><div class="head"><div><h1>Jornada</h1><div class="sub">Control de asistencia por sesión y clase</div></div></div><input id="fecha" class="fecha" type="date"><div id="resumen" class="resumen"></div><div class="jornada-actions"><button id="cancelarJornada" class="btn-danger">Cancelar jornada completa</button></div><div id="lista"></div></main><script>
const fecha=document.getElementById('fecha'),lista=document.getElementById('lista'),resumen=document.getElementById('resumen'),btnJornada=document.getElementById('cancelarJornada');fecha.value=new Date().toISOString().slice(0,10);fecha.onchange=cargar;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function asistencia(body){const r=await fetch('/api/asistencia.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}
async function cancelar(body){const r=await fetch('/api/cancelaciones-clases.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}
function pedirMotivo(texto){return prompt(texto+'\nMotivo de cancelación:')?.trim()||''}
function alumnoHtml(a,s){const acceso=!!a.puede_tomar_clase;const justificada=a.asistencia_estado==='AUSENTE_JUSTIFICADA';const ausencia=a.asistencia_estado==='AUSENTE_NO_JUSTIFICADA'||justificada;const etiqueta=a.intensivo_activo==1?'Intensivo':(acceso?'Con derecho a clase':'Sin derecho a clase');const controles=acceso&&!s.cerrada&&s.estado!=='CANCELADA'?`<div class="pase" data-s="${esc(s.id)}" data-a="${esc(a.id)}"><button class="vino ${a.asistencia_estado==='PRESENTE'?'sel':''}" data-e="PRESENTE">Vino</button><button class="no-vino ${ausencia?'sel':''}" data-e="AUSENTE_NO_JUSTIFICADA">No vino</button></div>`:'<span class="bloqueado">'+(s.estado==='CANCELADA'?'CLASE CANCELADA':(s.cerrada?'CLASE CERRADA':'BLOQUEADO'))+'</span>';return `<div class="alumno"><div><div class="nombre">${esc(a.nombre)}${justificada?'<span class="justificada">Justificada</span>':''}</div><div class="info ${acceso?'ok':'alerta'}">${esc(etiqueta)}${a.sesiones_semana?' · '+Number(a.sesiones_semana)+'×/sem':''}</div></div>${controles}</div>`}
function claseHtml(s){const cancel=s.estado==='CANCELADA';return `<article class="clase ${cancel?'cancelada':''}"><div class="clase-top"><div><div class="tipo">Clase</div><div class="hora">${esc((s.hora_inicio||'').slice(0,5))}–${esc((s.hora_fin||'').slice(0,5))}</div></div><span class="estado ${cancel?'cancel':''}">${esc(s.estado)}</span></div>${cancel&&s.motivo_cancelacion?`<div class="motivo">Cancelada: ${esc(s.motivo_cancelacion)}</div>`:''}${s.alumnos.length?s.alumnos.map(a=>alumnoHtml(a,s)).join(''):'<div class="vacio">Sin alumnos planificados.</div>'}${!s.cerrada?`<div class="clase-actions"><button class="cerrar" data-close="${esc(s.id)}">Cerrar clase</button><button class="cancelar" data-cancel-class="${esc(s.id)}">Cancelar clase</button></div>`:''}</article>`}
function sesionHtml(nombre,bloque,clases){if(!clases.length)return '';return `<section class="bloque"><div class="bloque-head"><div><div class="bloque-title">${esc(nombre)}</div><div class="bloque-sub">${clases.length} clase${clases.length===1?'':'s'} planificada${clases.length===1?'':'s'}</div></div><button class="bloque-cancel" data-cancel-session="${esc(bloque)}">Cancelar sesión</button></div>${clases.map(claseHtml).join('')}</section>`}
async function cargar(){lista.innerHTML='<div class="vacio">Preparando jornada…</div>';resumen.textContent='';btnJornada.style.display='';try{const r=await fetch('/api/asistencia.php?fecha='+fecha.value),d=await r.json();if(!d.ok)throw new Error(d.error);if(d.laborable===false){resumen.textContent='Fin de semana · sin jornada de clases.';btnJornada.style.display='none';lista.innerHTML='<div class="descanso"><strong>No hay clases</strong><span>Hache Natación imparte clases de lunes a viernes.</span></div>';return}resumen.textContent=d.sesiones_creadas?`Franky preparó ${d.sesiones_creadas} clase${d.sesiones_creadas===1?'':'s'} automáticamente.`:'Jornada preparada.';const am=d.sesiones.filter(s=>s.bloque==='AM'),pm=d.sesiones.filter(s=>s.bloque==='PM');if(!d.sesiones.length){lista.innerHTML='<div class="vacio">No hay clases planificadas para esta jornada.</div>';return}lista.innerHTML=sesionHtml('Sesión matutina','AM',am)+sesionHtml('Sesión vespertina','PM',pm);}catch(e){lista.innerHTML='<div class="vacio alerta">'+esc(e.message)+'</div>'}}
lista.onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.e){const g=b.parentElement;await asistencia({accion:'ASISTENCIA',sesion_id:g.dataset.s,alumno_id:g.dataset.a,estado:b.dataset.e});g.querySelectorAll('button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel')}else if(b.dataset.close){if(confirm('¿Cerrar esta clase como realizada?')){await asistencia({accion:'CERRAR',sesion_id:b.dataset.close});cargar()}}else if(b.dataset.cancelClass){const m=pedirMotivo('Cancelar solo esta clase.');if(m&&confirm('La cancelación afectará a todos los alumnos planificados en esta clase. ¿Continuar?')){await cancelar({nivel:'CLASE',clase_id:b.dataset.cancelClass,motivo:m});cargar()}}else if(b.dataset.cancelSession){const nombre=b.dataset.cancelSession==='AM'?'matutina':'vespertina';const m=pedirMotivo('Cancelar toda la sesión '+nombre+'.');if(m&&confirm('Se cancelarán todas las clases de la sesión '+nombre+'. ¿Continuar?')){await cancelar({nivel:'SESION',fecha:fecha.value,bloque:b.dataset.cancelSession,motivo:m});cargar()}}}catch(err){alert(err.message)}};
btnJornada.onclick=async()=>{const m=pedirMotivo('Cancelar la jornada completa.');if(!m)return;if(!confirm('Se cancelarán TODAS las clases de esta jornada. ¿Continuar?'))return;try{await cancelar({nivel:'JORNADA',fecha:fecha.value,motivo:m});cargar()}catch(e){alert(e.message)}};cargar();
</script></body></html>
